vector<vector<int>> matchOrders(vector<vector<int>>& ops) {
    // price levels: map<price, deque<id>> per side; id -> {side, price, remaining}
    map<int, deque<int>, greater<int>> bids; map<int, deque<int>> asks; unordered_map<int, array<int,3>> live; vector<vector<int>> tr;
    for (auto& o : ops) {
        if (o[0] == 2) { auto it = live.find(o[1]); if (it != live.end()) it->second[2] = 0; continue; }
        int side = o[0], id = o[1], px = o[2], qty = o[3];
        auto fill = [&](auto& opp, auto crosses) {
            while (qty && !opp.empty()) { auto lvl = opp.begin(); if (!crosses(lvl->first)) break; auto& q = lvl->second;
                while (qty && !q.empty()) { int rid = q.front(); auto& r = live[rid]; if (r[2] == 0) { q.pop_front(); live.erase(rid); continue; }
                    int x = min(qty, r[2]); qty -= x; r[2] -= x; tr.push_back(side == 0 ? vector<int>{id, rid, lvl->first, x} : vector<int>{rid, id, lvl->first, x}); if (r[2] == 0) { q.pop_front(); live.erase(rid); } }
                if (q.empty()) opp.erase(lvl); } };
        if (side == 0) fill(asks, [&](int a) { return a <= px; }); else fill(bids, [&](int b) { return b >= px; });
        if (qty) { live[id] = {side, px, qty}; if (side == 0) bids[px].push_back(id); else asks[px].push_back(id); }
    }
    return tr;
}
